struct Point {
    x: f64,
    y: f64,
}

impl Point {
    // Associated function (like a static method) — constructor by convention
    fn new(x: f64, y: f64) -&gt; Self {
        Point { x, y }   // field shorthand when names match
    }

    // Method — first arg is &self (immutable) or &mut self (mutable)
